import json
import sys
from pathlib import Path


def load_costs(directory: Path) -> list[float]:
    costs: list[float] = []
    for path in sorted(directory.glob("*.json")):
        if not path.is_file():
            continue
        with path.open() as f:
            data = json.load(f)
        if isinstance(data, dict) and "cost_usd" in data:
            costs.append(data["cost_usd"])
    return costs


def main() -> None:
    directory = Path(sys.argv[1])
    costs = load_costs(directory)
    total = sum(costs)
    mean = total / len(costs) if costs else 0

    summary = {"total": total, "mean": mean}
    with open("summary.json", "w") as f:
        json.dump(summary, f)


if __name__ == "__main__":
    main()
